#include <stdio.h>

struct Account {
    char name[50];
    float balance;
};

struct Account account;

void createAccount() {
    printf("Enter account holder name and initial balance: ");
    scanf("%s %f", account.name, &account.balance);
    printf("Account created for %s with balance %.2f\n", account.name, account.balance);
}

void deposit() {
    float amount;
    printf("Enter amount to deposit: ");
    scanf("%f", &amount);
    account.balance += amount;
    printf("Deposited %.2f. New balance: %.2f\n", amount, account.balance);
}

void withdraw() {
    float amount;
    printf("Enter amount to withdraw: ");
    scanf("%f", &amount);
    if (amount > account.balance) {
        printf("Insufficient balance.\n");
        return;
    }
    account.balance -= amount;
    printf("Withdrew %.2f. New balance: %.2f\n", amount, account.balance);
}

void checkBalance() {
    printf("Current balance: %.2f\n", account.balance);
}

int main() {
    int choice;
    do {
        printf("\n1. Create Account\n2. Deposit\n3. Withdraw\n4. Check Balance\n5. Exit\nChoice: ");
        scanf("%d", &choice);
        switch (choice) {
            case 1: createAccount(); break;
            case 2: deposit(); break;
            case 3: withdraw(); break;
            case 4: checkBalance(); break;
            case 5: printf("Exiting...\n"); break;
            default: printf("Invalid choice\n");
        }
    } while (choice != 5);
    return 0;
}
